insert into public.proyectos_ideas (id, area, areas2, titulo, resumen, tipo, tiempo, horas, etiquetas, intencion, datos, prog, busca, ficha, orden) values
('como-ha-cambiado-el-clima-de-tu-ciudad-en-los-ultimos-30-anos','ambiente',array['ciencias','tecnologia']::text[],'¿Cómo ha cambiado el clima de tu ciudad en los últimos 30 años?','Analiza datos meteorológicos públicos de tu ciudad para ver cómo han cambiado temperatura y lluvia en las últimas décadas, y qué tan claro es el cambio.','Análisis','~28 h',28,array['Clima','Datos']::text[],array['investigar']::text[],'publicos',NULL,'estadistica ciencia de datos fisica ingenieria ambiental geografia ingenieria civil ingenieria de sistemas matematica analisis de series temporales. limpieza de datos. visualizacion. pensamiento critico. datos de servicios meteorologicos. hoja de calculo o herramientas de programacion. herramientas de graficos.',$a46sld${"id": "como-ha-cambiado-el-clima-de-tu-ciudad-en-los-ultimos-30-anos", "area": "ambiente", "areas2": ["ciencias", "tecnologia"], "titulo": "¿Cómo ha cambiado el clima de tu ciudad en los últimos 30 años?", "resumen": "Analiza datos meteorológicos públicos de tu ciudad para ver cómo han cambiado temperatura y lluvia en las últimas décadas, y qué tan claro es el cambio.", "tipo": "Análisis", "tiempo": "~28 h", "horas": 28, "etiquetas": ["Clima", "Datos"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Estadística", "Ciencia de Datos", "Física", "Ingeniería Ambiental", "Geografía", "Ingeniería Civil", "Ingeniería de Sistemas", "Matemática"], "problema": ["Es común escuchar que el clima ya no es igual que antes, pero pocas personas revisan los datos de su propia ciudad. Las conversaciones se basan en recuerdos, que suelen ser poco fiables.", "Mirar series largas de datos permite ver tendencias, pero también obliga a entender que el clima varía de un año a otro y que no siempre es fácil distinguir un cambio real."], "desarrollar": ["Descarga datos públicos de temperatura y precipitación de una estación cercana y ordénalos por año y mes, revisando si hay vacíos o errores que debas explicar.", "Calcula promedios por década, grafica las tendencias y concluye qué cambios parecen claros y cuáles no, explicando las limitaciones, como la calidad de los datos o el cambio de ubicación de la estación."], "ampliaciones": [{"titulo": "Eventos extremos", "aporta": "cuenta cuántos días muy calurosos o de lluvia intensa hubo cada año."}, {"titulo": "Comparar ciudades", "aporta": "compara tus resultados con los de una ciudad distinta."}, {"titulo": "Explicarlo en gráficos", "aporta": "crea tres gráficos claros que cuenten la historia a un público general."}], "objetivos": ["Obtener y ordenar datos públicos.", "Revisar su calidad.", "Calcular y graficar tendencias.", "Comunicar los resultados con honestidad."], "habilidades": ["Análisis de series temporales.", "Limpieza de datos.", "Visualización.", "Pensamiento crítico."], "herramientas": ["Datos de servicios meteorológicos.", "Hoja de cálculo o herramientas de programación.", "Herramientas de gráficos."], "lineamientos": ["Cita el origen y el periodo de los datos y no afirmes causas del cambio sin fuentes: el análisis muestra qué cambió, no por qué.", "Si faltan datos, indícalo; no los completes sin explicar cómo lo hiciste."], "otroSector": "El mismo análisis de tendencias sirve para estudiar ventas, tráfico, precios, consumo de energía o cualquier serie de datos."}$a46sld$::jsonb,54),
('que-tan-verde-es-lo-que-dice-ser-verde-un-vistazo-al-greenwashin','ambiente',array['derecho','negocios']::text[],'¿Qué tan verde es lo que dice ser verde? Un vistazo al greenwashing','Revisa frases como «ecológico» o «amigable con el planeta» en productos y publicidad, y evalúa cuáles tienen sustento y cuáles son vagas o engañosas.','Análisis','~22 h',22,array['Publicidad','Etiquetas']::text[],array['investigar','resolver']::text[],'propios',NULL,'derecho comunicaciones publicidad administracion ingenieria ambiental economia psicologia quimica lectura critica de publicidad. analisis de afirmaciones. investigacion de normas. redaccion clara. envases y anuncios reales. criterios de organismos de proteccion al consumidor. hoja de calculo.',$a47sld${"id": "que-tan-verde-es-lo-que-dice-ser-verde-un-vistazo-al-greenwashin", "area": "ambiente", "areas2": ["derecho", "negocios"], "titulo": "¿Qué tan verde es lo que dice ser verde? Un vistazo al greenwashing", "resumen": "Revisa frases como «ecológico» o «amigable con el planeta» en productos y publicidad, y evalúa cuáles tienen sustento y cuáles son vagas o engañosas.", "tipo": "Análisis", "tiempo": "~22 h", "horas": 22, "etiquetas": ["Publicidad", "Etiquetas"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Derecho", "Comunicaciones", "Publicidad", "Administración", "Ingeniería Ambiental", "Economía", "Psicología", "Química"], "problema": ["Cada vez más productos se presentan como verdes, naturales o sostenibles, pero esas palabras no siempre significan lo mismo ni tienen respaldo. Algunas son afirmaciones vagas que suenan bien, pero no dicen nada comprobable.", "Para quien compra, es difícil distinguir lo que sí está certificado de lo que solo es publicidad. Ese problema afecta tanto a consumidores como a empresas que sí cumplen."], "desarrollar": ["Reúne entre diez y quince envases o anuncios con afirmaciones ambientales y clasifícalas: específicas y comprobables, vagas, o respaldadas por una certificación o un dato citado.", "Con criterios públicos de organismos de protección al consumidor o de publicidad responsable, evalúa cada afirmación y arma una guía breve de preguntas para reconocer las que conviene mirar con cuidado."], "ampliaciones": [{"titulo": "Revisar la norma", "aporta": "investiga qué dicen las normas sobre afirmaciones ambientales en publicidad."}, {"titulo": "Comparar sectores", "aporta": "compara cómo aparece el mensaje verde en alimentos, limpieza y ropa."}, {"titulo": "Reescribir el mensaje", "aporta": "propón cómo decir lo mismo de forma honesta y comprobable."}], "objetivos": ["Reunir ejemplos con criterio.", "Clasificar afirmaciones según su sustento.", "Aplicar criterios públicos.", "Comunicar una guía clara."], "habilidades": ["Lectura crítica de publicidad.", "Análisis de afirmaciones.", "Investigación de normas.", "Redacción clara."], "herramientas": ["Envases y anuncios reales.", "Criterios de organismos de protección al consumidor.", "Hoja de cálculo."], "lineamientos": ["Evalúa afirmaciones y no acuses de engaño a empresas concretas: trabaja con categorías y ejemplos neutros o anónimos.", "Cita los criterios que uses y distingue entre una afirmación vaga y una falsa, porque no es lo mismo."], "otroSector": "El mismo método sirve para revisar afirmaciones de salud, de seguridad, de precio o de calidad en cualquier tipo de publicidad."}$a47sld$::jsonb,55),
('que-residuos-de-un-negocio-de-barrio-podrian-servirle-a-otro','ambiente',array['negocios','industria']::text[],'¿Qué residuos de un negocio de barrio podrían servirle a otro?','Piensa en los desechos de comercios cercanos, como una panadería, una ferretería o una lavandería, y descubre cuáles podrían ser materia prima útil para otro negocio.','Análisis','~25 h',25,array['Economía circular','Negocios locales']::text[],array['investigar','resolver','otro-sector']::text[],'ficticios',NULL,'administracion ingenieria industrial economia ingenieria ambiental contabilidad ingenieria agroindustrial trabajo social ingenieria de sistemas analisis de cadenas de valor. pensamiento sistemico. evaluacion de viabilidad. comunicacion visual. un editor de diagramas o de mapas conceptuales. hoja de calculo. informacion publica del sector.',$a48sld${"id": "que-residuos-de-un-negocio-de-barrio-podrian-servirle-a-otro", "area": "ambiente", "areas2": ["negocios", "industria"], "titulo": "¿Qué residuos de un negocio de barrio podrían servirle a otro?", "resumen": "Piensa en los desechos de comercios cercanos, como una panadería, una ferretería o una lavandería, y descubre cuáles podrían ser materia prima útil para otro negocio.", "tipo": "Análisis", "tiempo": "~25 h", "horas": 25, "etiquetas": ["Economía circular", "Negocios locales"], "intencion": ["investigar", "resolver", "otro-sector"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Administración", "Ingeniería Industrial", "Economía", "Ingeniería Ambiental", "Contabilidad", "Ingeniería Agroindustrial", "Trabajo Social", "Ingeniería de Sistemas"], "problema": ["Lo que un negocio desecha a veces es justo lo que otro necesita: pan viejo, aserrín, cajas, aceite, retazos o envases. Pero rara vez se encuentran porque cada negocio trabaja por separado.", "Conectarlos reduciría residuos y costos para ambos lados. Falta información sobre qué se desecha, en qué cantidad y quién podría aprovecharlo."], "desarrollar": ["Elige una calle comercial o un mercado, real o inventado, describe seis a ocho tipos de negocio y para cada uno estima qué residuos genera y en qué cantidad aproximada, con casos de ejemplo o información pública.", "Dibuja un mapa de conexiones que indique qué residuo podría convertirse en insumo para otro negocio y evalúa qué haría falta, como transporte, limpieza o acuerdos, para que ocurra."], "ampliaciones": [{"titulo": "Valor del residuo", "aporta": "estima cuánto dinero aportaría cada conexión."}, {"titulo": "Obstáculos", "aporta": "identifica qué impediría que dos negocios colaboren, como higiene, tiempos o confianza."}, {"titulo": "Prueba piloto", "aporta": "diseña una prueba entre dos negocios durante un mes."}], "objetivos": ["Identificar residuos de distintos negocios.", "Reconocer posibles usos en otros.", "Representar las conexiones.", "Evaluar su viabilidad."], "habilidades": ["Análisis de cadenas de valor.", "Pensamiento sistémico.", "Evaluación de viabilidad.", "Comunicación visual."], "herramientas": ["Un editor de diagramas o de mapas conceptuales.", "Hoja de cálculo.", "Información pública del sector."], "lineamientos": ["Si hablas con negocios reales, pide permiso, explica el propósito y no publiques datos sin su acuerdo; si no, trabaja con casos ficticios.", "No propongas reutilizar residuos de alimentos o peligrosos sin tener en cuenta la normativa sanitaria."], "otroSector": "El mismo mapa de conexiones sirve para pensar en cómo comparten recursos empresas de una zona industrial o instituciones de una misma ciudad."}$a48sld$::jsonb,56),
('el-trabajo-invisible-del-reciclaje-quien-recupera-los-residuos-e','ambiente',array['sociedad','derecho']::text[],'El trabajo invisible del reciclaje: ¿quién recupera los residuos en tu ciudad?','Descubre quiénes, a menudo sin reconocimiento, recuperan y venden los materiales reciclables, cómo funciona esa cadena y qué se hace para formalizarla.','Investigación','~25 h',25,array['Reciclaje','Trabajo']::text[],array['investigar']::text[],'publicos',NULL,'sociologia trabajo social derecho economia ingenieria ambiental antropologia administracion comunicaciones investigacion de fuentes. analisis social y economico. pensamiento critico. redaccion clara. informes y normas publicas. hoja de calculo. un editor de infografias.',$a49sld${"id": "el-trabajo-invisible-del-reciclaje-quien-recupera-los-residuos-e", "area": "ambiente", "areas2": ["sociedad", "derecho"], "titulo": "El trabajo invisible del reciclaje: ¿quién recupera los residuos en tu ciudad?", "resumen": "Descubre quiénes, a menudo sin reconocimiento, recuperan y venden los materiales reciclables, cómo funciona esa cadena y qué se hace para formalizarla.", "tipo": "Investigación", "tiempo": "~25 h", "horas": 25, "etiquetas": ["Reciclaje", "Trabajo"], "intencion": ["investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Sociología", "Trabajo Social", "Derecho", "Economía", "Ingeniería Ambiental", "Antropología", "Administración", "Comunicaciones"], "problema": ["Buena parte de lo que se recicla en muchas ciudades no lo recupera un sistema formal sino personas que trabajan recolectando, clasificando y vendiendo materiales. Ese trabajo sostiene una parte de la cadena, pero suele ser invisible para quienes separan en casa.", "Sin entenderlo, las propuestas de reciclaje pueden ignorar o incluso afectar a quienes viven de él, y pierden aliados valiosos."], "desarrollar": ["Con informes públicos, normas y reportes de organizaciones que trabajan con recicladores, reconstruye cómo funciona la cadena: quiénes participan, qué materiales manejan, cuánto se paga y qué avances o dificultades hay para su formalización.", "Resume en un documento o infografía los hallazgos, los datos que no encontraste y propón dos ideas para que las campañas de reciclaje tomen en cuenta a quienes ya hacen el trabajo."], "ampliaciones": [{"titulo": "Marco legal", "aporta": "revisa las normas que regulan la actividad y su alcance."}, {"titulo": "Cadena de precios", "aporta": "reconstruye cuánto se paga por cada material en cada etapa."}, {"titulo": "Comparar países", "aporta": "estudia cómo otros países incluyen a los recicladores en sus sistemas."}], "objetivos": ["Buscar información de fuentes confiables.", "Reconstruir la cadena de valor.", "Reconocer el rol de los distintos actores.", "Proponer acciones con enfoque inclusivo."], "habilidades": ["Investigación de fuentes.", "Análisis social y económico.", "Pensamiento crítico.", "Redacción clara."], "herramientas": ["Informes y normas públicas.", "Hoja de cálculo.", "Un editor de infografías."], "lineamientos": ["Usa fuentes públicas o hechas por las propias organizaciones; no abordes a recicladores ni fotografíes su trabajo sin su consentimiento y un propósito claro.", "Habla con respeto y sin estereotipos, y deja claro que tu estudio es una aproximación que ellos mismos podrían corregir."], "otroSector": "El mismo enfoque sirve para estudiar otros trabajos poco visibles, como el cuidado, el comercio ambulante o la economía informal."}$a49sld$::jsonb,57),
('que-zonas-de-tu-distrito-son-mas-vulnerables-a-huaicos-o-inundac','ambiente',array['ciudades','sociedad']::text[],'¿Qué zonas de tu distrito son más vulnerables a huaicos o inundaciones?','Cruza mapas públicos de riesgo con información de población y servicios para descubrir qué zonas serían más afectadas por huaicos, lluvias intensas o inundaciones.','Análisis','~30 h',30,array['Riesgos','Mapas']::text[],array['investigar','resolver']::text[],'publicos',NULL,'ingenieria civil ingenieria geologica geografia ingenieria ambiental sociologia estadistica ciencia de datos arquitectura lectura de mapas de riesgo. analisis espacial. uso de datos publicos. comunicacion de riesgos. mapas y reportes de organismos de gestion de riesgos. un editor de mapas digitales. hoja de calculo.',$a50sld${"id": "que-zonas-de-tu-distrito-son-mas-vulnerables-a-huaicos-o-inundac", "area": "ambiente", "areas2": ["ciudades", "sociedad"], "titulo": "¿Qué zonas de tu distrito son más vulnerables a huaicos o inundaciones?", "resumen": "Cruza mapas públicos de riesgo con información de población y servicios para descubrir qué zonas serían más afectadas por huaicos, lluvias intensas o inundaciones.", "tipo": "Análisis", "tiempo": "~30 h", "horas": 30, "etiquetas": ["Riesgos", "Mapas"], "intencion": ["investigar", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Ingeniería Civil", "Ingeniería Geológica", "Geografía", "Ingeniería Ambiental", "Sociología", "Estadística", "Ciencia de Datos", "Arquitectura"], "problema": ["Cada temporada de lluvias se repiten daños en quebradas, ríos y laderas, y los más afectados suelen ser quienes viven en zonas más expuestas. Los mapas de riesgo existen, pero casi nadie los lee ni los cruza con quién vive ahí.", "Entender dónde está el peligro y quién lo enfrenta permite orientar mejor la prevención y la atención, antes de que ocurra un desastre."], "desarrollar": ["Con mapas y reportes públicos de organismos de gestión de riesgos de tu país, ubica las zonas de peligro por huaicos o inundaciones en un distrito, y reúne datos públicos de población, escuelas, centros de salud y vías en esas zonas.", "Elabora un mapa que combine peligro y exposición, destaca las zonas más críticas y explica qué acciones de prevención recomiendan las fuentes oficiales."], "ampliaciones": [{"titulo": "Rutas de evacuación", "aporta": "revisa qué vías y puntos seguros existen en las zonas más críticas."}, {"titulo": "Historia de eventos", "aporta": "ubica en el mapa los eventos de años anteriores."}, {"titulo": "Mensaje a la comunidad", "aporta": "convierte los hallazgos en un material claro para quienes viven allí."}], "objetivos": ["Usar mapas de riesgo de fuentes oficiales.", "Cruzar peligro con exposición.", "Representarlo con claridad.", "Comunicar con responsabilidad."], "habilidades": ["Lectura de mapas de riesgo.", "Análisis espacial.", "Uso de datos públicos.", "Comunicación de riesgos."], "herramientas": ["Mapas y reportes de organismos de gestión de riesgos.", "Un editor de mapas digitales.", "Hoja de cálculo."], "lineamientos": ["Trabaja solo con fuentes oficiales, citándolas, y no afirmes que una vivienda o familia concreta está en riesgo: habla de zonas.", "No difundas el mapa como si fuera una alerta oficial; para emergencias, remite siempre a las autoridades."], "otroSector": "El mismo cruce de peligro y exposición sirve para analizar riesgos de sismo, de incendio, de contaminación o de interrupción de servicios."}$a50sld$::jsonb,58),
('que-cuenta-la-basura-de-un-espacio-publico','ambiente',array['sociedad','ciudades']::text[],'¿Qué cuenta la basura de un espacio público?','Cuenta y clasifica los residuos que encuentras en un parque, una playa o una calle para descubrir qué se tira, dónde y qué dice eso de los hábitos y de los servicios.','Análisis','~18 h',18,array['Residuos','Espacio público']::text[],array['investigar','resolver']::text[],'propios',NULL,'sociologia antropologia ingenieria ambiental estadistica geografia educacion comunicaciones trabajo social trabajo de campo. clasificacion de datos. analisis basico. propuestas de mejora. guantes y bolsas. hoja de registro. hoja de calculo.',$a51sld${"id": "que-cuenta-la-basura-de-un-espacio-publico", "area": "ambiente", "areas2": ["sociedad", "ciudades"], "titulo": "¿Qué cuenta la basura de un espacio público?", "resumen": "Cuenta y clasifica los residuos que encuentras en un parque, una playa o una calle para descubrir qué se tira, dónde y qué dice eso de los hábitos y de los servicios.", "tipo": "Análisis", "tiempo": "~18 h", "horas": 18, "etiquetas": ["Residuos", "Espacio público"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Sociología", "Antropología", "Ingeniería Ambiental", "Estadística", "Geografía", "Educación", "Comunicaciones", "Trabajo Social"], "problema": ["La basura en un parque o una playa parece un problema evidente, pero casi nunca se mira con orden: ¿qué se tira?, ¿en qué lugares?, ¿faltan tachos? Los datos podrían decir si el problema es de hábito, de servicios o de ambas cosas.", "Sin conteo, cada discusión se queda en opiniones. Con datos, se pueden hacer propuestas concretas."], "desarrollar": ["Elige un espacio público seguro y delimita una zona, y un día recoge con guantes y clasifica los residuos que veas, anotando tipos, cantidades y ubicación, y si hay tachos cerca.", "Haz gráficos por tipo y por lugar, identifica los objetos más frecuentes y propón dos o tres medidas que atiendan las causas, como más tachos, mensajes o cambios en lo que se vende."], "ampliaciones": [{"titulo": "Repetir en otro día", "aporta": "compara un día de semana con un fin de semana o un feriado."}, {"titulo": "Rastrear el origen", "aporta": "analiza qué marcas o tipos de producto aparecen más, sin señalar culpables."}, {"titulo": "Jornada de limpieza", "aporta": "diseña una jornada que combine limpieza y conteo."}], "objetivos": ["Delimitar y planificar el conteo.", "Registrar residuos con criterios claros.", "Visualizar resultados.", "Proponer medidas basadas en los datos."], "habilidades": ["Trabajo de campo.", "Clasificación de datos.", "Análisis básico.", "Propuestas de mejora."], "herramientas": ["Guantes y bolsas.", "Hoja de registro.", "Hoja de cálculo."], "lineamientos": ["Usa guantes, no recojas objetos punzocortantes, jeringas ni residuos peligrosos y avisa a las autoridades si los encuentras.", "Trabaja en lugares seguros y de día, de preferencia acompañado, y pide permiso si el lugar es administrado por alguien."], "otroSector": "El mismo conteo sirve para estudiar cómo se usa un espacio público: sillas ocupadas, personas que pasan o servicios que faltan."}$a51sld$::jsonb,59),
('cuanto-cuesta-ser-sostenible-y-cuanto-se-ahorra','ambiente',array['negocios','sociedad']::text[],'¿Cuánto cuesta ser sostenible, y cuánto se ahorra?','Compara el costo inicial y el ahorro a lo largo del tiempo de decisiones sostenibles, como un foco LED, una botella reutilizable o reparar en vez de comprar, para ver cuáles convienen.','Análisis','~20 h',20,array['Costos','Consumo']::text[],array['investigar','resolver']::text[],'publicos',NULL,'economia contabilidad administracion ingenieria ambiental estadistica ingenieria industrial psicologia educacion analisis de costos y beneficios. busqueda de datos. calculo financiero basico. comunicacion clara. hoja de calculo. precios publicados de tiendas. datos de duracion de fabricantes.',$a52sld${"id": "cuanto-cuesta-ser-sostenible-y-cuanto-se-ahorra", "area": "ambiente", "areas2": ["negocios", "sociedad"], "titulo": "¿Cuánto cuesta ser sostenible, y cuánto se ahorra?", "resumen": "Compara el costo inicial y el ahorro a lo largo del tiempo de decisiones sostenibles, como un foco LED, una botella reutilizable o reparar en vez de comprar, para ver cuáles convienen.", "tipo": "Análisis", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Costos", "Consumo"], "intencion": ["investigar", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Economía", "Contabilidad", "Administración", "Ingeniería Ambiental", "Estadística", "Ingeniería Industrial", "Psicología", "Educación"], "problema": ["Se dice que ser sostenible es caro, pero a veces es al revés: lo que cuesta más al comprar se ahorra con el uso. Pocas personas hacen esa cuenta, y deciden solo por el precio de hoy.", "Y también hay casos en que sí cuesta más. Distinguir cuáles son ayuda a priorizar y a ser honesto sobre las dificultades de quien tiene un presupuesto ajustado."], "desarrollar": ["Elige entre seis y ocho opciones sostenibles de uso cotidiano, y para cada una busca el costo inicial, el costo de uso y la duración con datos citados, y compara con la alternativa convencional.", "Calcula el costo a uno, tres y cinco años, destaca en qué casos conviene y en cuáles no, y arma una tabla clara con los resultados."], "ampliaciones": [{"titulo": "Presupuesto ajustado", "aporta": "identifica qué opciones son accesibles para quien tiene pocos recursos."}, {"titulo": "Cuándo se recupera", "aporta": "calcula en cuántos meses se recupera cada inversión."}, {"titulo": "Subsidios o ayudas", "aporta": "investiga qué programas pueden hacer accesibles las opciones más caras."}], "objetivos": ["Reunir datos de costos con fuentes.", "Calcular costos a lo largo del tiempo.", "Comparar con criterios claros.", "Comunicar los resultados sin sesgo."], "habilidades": ["Análisis de costos y beneficios.", "Búsqueda de datos.", "Cálculo financiero básico.", "Comunicación clara."], "herramientas": ["Hoja de cálculo.", "Precios publicados de tiendas.", "Datos de duración de fabricantes."], "lineamientos": ["Usa precios que puedas citar con fecha y evita presentar el resultado como válido para todos los casos.", "No compares marcas ni recomiendes comprar productos concretos: analiza tipos de opción."], "otroSector": "El mismo análisis de costo a lo largo del tiempo sirve para decidir entre comprar y alquilar, entre mantener y renovar o entre invertir y esperar."}$a52sld$::jsonb,60),
('una-norma-ambiental-explicada-para-todos','ambiente',array['derecho','educacion']::text[],'Una norma ambiental explicada para todos','Elige una norma sobre residuos, agua, ruido o áreas verdes y tradúcela a un lenguaje claro: qué dice, a quién le toca qué y cómo se hace valer.','Guía','~22 h',22,array['Normas','Divulgación']::text[],array['crear','investigar']::text[],'publicos',NULL,'derecho ciencia politica comunicaciones ingenieria ambiental educacion diseno grafico administracion sociologia lectura de normas. redaccion en lenguaje claro. sintesis. diseno de informacion. el texto oficial de la norma. un editor de documentos o de diseno. un formulario de prueba.',$a53sld${"id": "una-norma-ambiental-explicada-para-todos", "area": "ambiente", "areas2": ["derecho", "educacion"], "titulo": "Una norma ambiental explicada para todos", "resumen": "Elige una norma sobre residuos, agua, ruido o áreas verdes y tradúcela a un lenguaje claro: qué dice, a quién le toca qué y cómo se hace valer.", "tipo": "Guía", "tiempo": "~22 h", "horas": 22, "etiquetas": ["Normas", "Divulgación"], "intencion": ["crear", "investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Derecho", "Ciencia Política", "Comunicaciones", "Ingeniería Ambiental", "Educación", "Diseño Gráfico", "Administración", "Sociología"], "problema": ["Las normas ambientales existen, pero casi nadie las conoce porque están escritas para especialistas. Muchas personas no saben cuáles son sus deberes, qué pueden exigir ni a dónde acudir.", "Una norma que no se entiende no se cumple ni se puede reclamar. Explicarla con claridad es una forma de ejercer ciudadanía."], "desarrollar": ["Elige una norma vigente que te interese, léela completa y subraya a quién va dirigida, qué obliga o prohíbe, qué sanciones prevé y qué instancia la supervisa.", "Redáctala en una guía de una a dos páginas en lenguaje sencillo, con ejemplos de la vida diaria, y pide a dos personas que no sean de Derecho que la lean y te digan qué no entendieron."], "ampliaciones": [{"titulo": "Preguntas frecuentes", "aporta": "arma una lista de preguntas y respuestas basadas en la norma."}, {"titulo": "Cómo reclamar", "aporta": "explica el camino para hacer un reclamo o una denuncia paso a paso."}, {"titulo": "Comparar con otro país", "aporta": "compara cómo regula el mismo tema otro país."}], "objetivos": ["Comprender una norma completa.", "Identificar obligaciones y derechos.", "Redactar en lenguaje claro.", "Probar la comprensión con lectores."], "habilidades": ["Lectura de normas.", "Redacción en lenguaje claro.", "Síntesis.", "Diseño de información."], "herramientas": ["El texto oficial de la norma.", "Un editor de documentos o de diseño.", "Un formulario de prueba."], "lineamientos": ["Usa el texto oficial vigente, cita el artículo de cada afirmación y aclara que la guía es informativa y no asesoría legal.", "Revisa que la norma no haya sido modificada y anota la fecha de consulta."], "otroSector": "La misma traducción a lenguaje claro sirve para contratos, normas de seguridad, reglamentos de una institución o trámites."}$a53sld$::jsonb,61),
('se-puede-cosechar-agua-de-la-neblina','ambiente',array['ciudades','ciencias']::text[],'¿Se puede "cosechar" agua de la neblina?','Investiga cómo se capta agua de la neblina con mallas y evalúa con datos públicos si tendría sentido en una zona de tu país donde la neblina es frecuente.','Análisis','~25 h',25,array['Agua','Neblina']::text[],array['investigar','resolver']::text[],'publicos',NULL,'ingenieria civil ingenieria ambiental fisica geografia ingenieria mecanica estadistica arquitectura ingenieria agricola investigacion de fuentes. interpretacion de datos climaticos. evaluacion de viabilidad. comunicacion clara. informes de proyectos de captacion de niebla. datos de servicios meteorologicos. hoja de calculo.',$a54sld${"id": "se-puede-cosechar-agua-de-la-neblina", "area": "ambiente", "areas2": ["ciudades", "ciencias"], "titulo": "¿Se puede \"cosechar\" agua de la neblina?", "resumen": "Investiga cómo se capta agua de la neblina con mallas y evalúa con datos públicos si tendría sentido en una zona de tu país donde la neblina es frecuente.", "tipo": "Análisis", "tiempo": "~25 h", "horas": 25, "etiquetas": ["Agua", "Neblina"], "intencion": ["investigar", "resolver"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Ingeniería Civil", "Ingeniería Ambiental", "Física", "Geografía", "Ingeniería Mecánica", "Estadística", "Arquitectura", "Ingeniería Agrícola"], "problema": ["En algunas zonas costeras y de laderas la neblina es frecuente y la lluvia casi no existe. Captar sus gotas con mallas ha servido en distintos lugares del mundo para obtener agua, pero depende de factores como el viento, la humedad y el relieve.", "No es una solución mágica y no sirve en cualquier lugar. Saber cuándo sí y cuándo no requiere mirar datos con cuidado."], "desarrollar": ["Con fuentes públicas, resume cómo funcionan los captadores de niebla, qué condiciones necesitan y qué cantidades se han logrado en proyectos documentados.", "Elige una zona de tu país, busca sus datos de humedad, viento y neblina y evalúa de forma cualitativa y con cálculos simples si podría ser viable, qué uso tendría el agua y qué dificultades habría."], "ampliaciones": [{"titulo": "Diseñar un prototipo", "aporta": "dibuja el diseño de un captador pequeño con materiales y medidas."}, {"titulo": "Comparar zonas", "aporta": "compara dos lugares y explica cuál es más adecuado."}, {"titulo": "Costo y mantenimiento", "aporta": "estima qué costaría mantener el sistema funcionando."}], "objetivos": ["Comprender cómo funciona la captación.", "Reunir datos climáticos de una zona.", "Evaluar la viabilidad con criterio.", "Presentar resultados y límites."], "habilidades": ["Investigación de fuentes.", "Interpretación de datos climáticos.", "Evaluación de viabilidad.", "Comunicación clara."], "herramientas": ["Informes de proyectos de captación de niebla.", "Datos de servicios meteorológicos.", "Hoja de cálculo."], "lineamientos": ["Cita las fuentes de cada dato y aclara que el análisis es preliminar y no un diseño de ingeniería.", "No instales estructuras en espacios públicos sin permiso y no uses esta agua para consumo sin tratamiento."], "otroSector": "La misma lógica de evaluar si un recurso tiene sentido en un lugar sirve para el viento, el sol o la geotermia."}$a54sld$::jsonb,62),
('como-podria-el-cambio-climatico-cambiar-tu-profesion','ambiente',array['sociedad','educacion']::text[],'¿Cómo podría el cambio climático cambiar tu profesión?','Explora cómo los cambios del clima ya afectan o podrían afectar el trabajo de tu carrera, y qué nuevas oportunidades y habilidades aparecerían.','Investigación','~22 h',22,array['Clima','Profesiones']::text[],array['investigar','otro-sector']::text[],'publicos',NULL,'todas las carreras contabilidad derecho medicina administracion arquitectura economia educacion investigacion de fuentes. pensamiento prospectivo. sintesis. comunicacion clara. informes de organismos y colegios profesionales. un editor de documentos o presentaciones. hoja de calculo.',$a55sld${"id": "como-podria-el-cambio-climatico-cambiar-tu-profesion", "area": "ambiente", "areas2": ["sociedad", "educacion"], "titulo": "¿Cómo podría el cambio climático cambiar tu profesión?", "resumen": "Explora cómo los cambios del clima ya afectan o podrían afectar el trabajo de tu carrera, y qué nuevas oportunidades y habilidades aparecerían.", "tipo": "Investigación", "tiempo": "~22 h", "horas": 22, "etiquetas": ["Clima", "Profesiones"], "intencion": ["investigar", "otro-sector"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Todas las carreras", "Contabilidad", "Derecho", "Medicina", "Administración", "Arquitectura", "Economía", "Educación"], "problema": ["Se habla del cambio climático como un tema de ambientalistas, pero afecta a casi todas las profesiones: a los contadores por los riesgos y reportes, a los abogados por nuevas normas, a los médicos por enfermedades, a los arquitectos por el calor.", "Muchas personas no se imaginan cómo toca su carrera, y por eso no se preparan ni ven las oportunidades que se abren."], "desarrollar": ["Elige tu carrera y busca en fuentes públicas, como informes de organismos internacionales, colegios profesionales y universidades, cómo se espera que el clima cambie el trabajo de esa profesión.", "Resume tres impactos y tres oportunidades en un documento o una presentación, con ejemplos concretos, y reflexiona qué habilidades convendría desarrollar."], "ampliaciones": [{"titulo": "Entrevistar a un profesional", "aporta": "pregunta a alguien de tu campo cómo lo ve, con su consentimiento."}, {"titulo": "Comparar carreras", "aporta": "compara cómo afecta a dos profesiones muy distintas."}, {"titulo": "Plan de habilidades", "aporta": "arma una lista de cursos o prácticas que te prepararían."}], "objetivos": ["Buscar información de fuentes confiables.", "Relacionar el clima con tu campo profesional.", "Distinguir riesgos y oportunidades.", "Reflexionar sobre tu desarrollo."], "habilidades": ["Investigación de fuentes.", "Pensamiento prospectivo.", "Síntesis.", "Comunicación clara."], "herramientas": ["Informes de organismos y colegios profesionales.", "Un editor de documentos o presentaciones.", "Hoja de cálculo."], "lineamientos": ["Cita las fuentes y distingue lo que está documentado de lo que tú proyectas; evita presentar predicciones como hechos.", "No hagas afirmaciones sobre empresas o personas concretas."], "otroSector": "El mismo ejercicio sirve para analizar cómo la inteligencia artificial, la automatización o un cambio normativo afectarían a una profesión."}$a55sld$::jsonb,63),
('que-pescado-compras-y-cuando-conviene-no-hacerlo','ambiente',array['agricultura','negocios']::text[],'¿Qué pescado compras y cuándo conviene no hacerlo?','Arma un calendario de pescados y mariscos con sus temporadas, tallas mínimas y vedas oficiales, para comprar de forma más responsable.','Guía','~20 h',20,array['Pesca','Consumo responsable']::text[],array['crear','investigar']::text[],'publicos',NULL,'biologia ingenieria pesquera ingenieria ambiental nutricion administracion economia derecho comunicaciones investigacion de fuentes oficiales. organizacion de informacion. diseno de informacion. comunicacion clara. normas y comunicados de instituciones pesqueras. un editor de diseno. hoja de calculo.',$a56sld${"id": "que-pescado-compras-y-cuando-conviene-no-hacerlo", "area": "ambiente", "areas2": ["agricultura", "negocios"], "titulo": "¿Qué pescado compras y cuándo conviene no hacerlo?", "resumen": "Arma un calendario de pescados y mariscos con sus temporadas, tallas mínimas y vedas oficiales, para comprar de forma más responsable.", "tipo": "Guía", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Pesca", "Consumo responsable"], "intencion": ["crear", "investigar"], "datos": "publicos", "datosTexto": "públicos: trabaja con informes, estadísticas y registros que publican instituciones y fuentes abiertas.", "carreras": ["Biología", "Ingeniería Pesquera", "Ingeniería Ambiental", "Nutrición", "Administración", "Economía", "Derecho", "Comunicaciones"], "problema": ["Hay especies marinas que se consumen todo el año sin pensar que, en ciertos meses, se protege su reproducción con vedas. Comprar en esa época o ejemplares muy pequeños puede perjudicar la sostenibilidad de la pesca.", "La información sobre temporadas, tallas mínimas y vedas existe, pero está dispersa en normas y comunicados que casi nadie consulta al hacer la compra."], "desarrollar": ["Con fuentes oficiales de instituciones pesqueras, elige entre ocho y diez especies de consumo común en tu zona y reúne de cada una su temporada, su talla mínima y sus vedas.", "Presenta la información en un calendario o tarjeta fácil de consultar en un mercado, con enlaces a la fuente oficial, y pruébalo con alguien que compre pescado con frecuencia."], "ampliaciones": [{"titulo": "Tabla de alternativas", "aporta": "propón especies alternativas para cuando una está en veda."}, {"titulo": "Preguntas al comprar", "aporta": "crea una tarjeta con tres preguntas para hacer al vendedor."}, {"titulo": "Versión para restaurantes", "aporta": "adáptalo para que lo usen negocios de comida."}], "objetivos": ["Reunir información oficial.", "Organizarla en un formato claro.", "Redactar en lenguaje sencillo.", "Probarlo con usuarios."], "habilidades": ["Investigación de fuentes oficiales.", "Organización de información.", "Diseño de información.", "Comunicación clara."], "herramientas": ["Normas y comunicados de instituciones pesqueras.", "Un editor de diseño.", "Hoja de cálculo."], "lineamientos": ["Usa solo las normas vigentes y cita la fuente y la fecha de cada dato, porque las vedas y tallas se actualizan.", "No señales a vendedores ni a marcas; aclara que es una guía informativa."], "otroSector": "El mismo calendario sirve para frutas y verduras de temporada, para festivales gastronómicos o para productos agrícolas con épocas de siembra."}$a56sld$::jsonb,64),
('proyecto-de-intercambio-y-reutilizacion-de-objetos','sociedad',array['ambiente','negocios']::text[],'Proyecto de intercambio y reutilización de objetos','Diseña una forma sencilla de que una comunidad intercambie, preste o regale objetos que ya no usa, y piensa cómo hacerla confiable, ordenada y fácil de mantener.','Plan','~25 h',25,array['Intercambio','Comunidad']::text[],array['crear','resolver']::text[],'ficticios',NULL,'trabajo social sociologia administracion comunicaciones educacion ingenieria industrial economia ingenieria de sistemas diseno de servicios. organizacion comunitaria. redaccion de reglas claras. planificacion. un editor de diagramas o de documentos. hoja de calculo. un formulario de prueba.',$a57sld${"id": "proyecto-de-intercambio-y-reutilizacion-de-objetos", "area": "sociedad", "areas2": ["ambiente", "negocios"], "titulo": "Proyecto de intercambio y reutilización de objetos", "resumen": "Diseña una forma sencilla de que una comunidad intercambie, preste o regale objetos que ya no usa, y piensa cómo hacerla confiable, ordenada y fácil de mantener.", "tipo": "Plan", "tiempo": "~25 h", "horas": 25, "etiquetas": ["Intercambio", "Comunidad"], "intencion": ["crear", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Trabajo Social", "Sociología", "Administración", "Comunicaciones", "Educación", "Ingeniería Industrial", "Economía", "Ingeniería de Sistemas"], "problema": ["Muchas casas guardan objetos que otras personas necesitan: libros, ropa, herramientas, juguetes, útiles. Pero no existe una forma cómoda de encontrarse, y regalar o intercambiar con desconocidos genera dudas de confianza y logística.", "Cuando intercambiar es incómodo, los objetos terminan en la basura o guardados para siempre, mientras alguien más los compra nuevos."], "desarrollar": ["Elige una comunidad, como una facultad, un edificio o un barrio, y define qué objetos se podrían intercambiar, cómo se publicarían, cómo se acordaría la entrega y qué reglas básicas de confianza y de cuidado se necesitarían.", "Prepara el plan con un esquema del proceso, las reglas, un ejemplo de publicación y los materiales que harían falta, y revisa con alguien externo si queda claro y atractivo."], "ampliaciones": [{"titulo": "Primer evento", "aporta": "diseña una jornada de intercambio de un día, con horarios y responsables."}, {"titulo": "Versión digital", "aporta": "propón cómo sería un grupo o página para publicar y coordinar los intercambios."}, {"titulo": "Efecto estimado", "aporta": "estima cuántos objetos se reutilizarían y cuánto ahorro supondría."}], "objetivos": ["Identificar qué objetos tienen más demanda.", "Diseñar un proceso de intercambio claro.", "Definir reglas de confianza y seguridad.", "Evaluar la viabilidad del plan."], "habilidades": ["Diseño de servicios.", "Organización comunitaria.", "Redacción de reglas claras.", "Planificación."], "herramientas": ["Un editor de diagramas o de documentos.", "Hoja de cálculo.", "Un formulario de prueba."], "lineamientos": ["Incluye reglas de seguridad para los encuentros, como realizarlos en lugares públicos, y evita objetos peligrosos, vencidos o de uso personal.", "Si luego lo llevas a la práctica, hazlo con permiso de la institución o del lugar y sin recoger datos personales de más."], "otroSector": "El mismo diseño sirve para bancos de tiempo, préstamo de herramientas, bibliotecas comunitarias o redes de ayuda entre vecinos."}$a57sld$::jsonb,10),
('mapa-de-areas-verdes-y-sombra-de-tu-comunidad','ciudades',array['ambiente','salud']::text[],'Mapa de áreas verdes y sombra de tu comunidad','Registra las áreas verdes, los árboles y la sombra disponibles en tu barrio, y descubre qué zonas tienen más o menos acceso a ellas.','Análisis','~25 h',25,array['Áreas verdes','Mapas']::text[],array['investigar','resolver']::text[],'propios',NULL,'arquitectura geografia ingenieria civil ingenieria ambiental ciencia de datos sociologia estadistica ingenieria de sistemas trabajo de campo. lectura y creacion de mapas. analisis espacial basico. comunicacion de resultados. un mapa digital o una imagen satelital. cuaderno de campo. hoja de calculo.',$a58sld${"id": "mapa-de-areas-verdes-y-sombra-de-tu-comunidad", "area": "ciudades", "areas2": ["ambiente", "salud"], "titulo": "Mapa de áreas verdes y sombra de tu comunidad", "resumen": "Registra las áreas verdes, los árboles y la sombra disponibles en tu barrio, y descubre qué zonas tienen más o menos acceso a ellas.", "tipo": "Análisis", "tiempo": "~25 h", "horas": 25, "etiquetas": ["Áreas verdes", "Mapas"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Arquitectura", "Geografía", "Ingeniería Civil", "Ingeniería Ambiental", "Ciencia de Datos", "Sociología", "Estadística", "Ingeniería de Sistemas"], "problema": ["En muchas ciudades las áreas verdes no se reparten por igual: hay barrios con parques y árboles y otros casi sin sombra. Esa diferencia afecta el calor, el bienestar y las posibilidades de descanso y de juego.", "Pocas veces se cuenta con un mapa claro de qué hay realmente, y sin él es difícil argumentar dónde falta."], "desarrollar": ["Elige una zona de tu comunidad, recórrela y registra en un mapa los parques, jardines, árboles de calle y lugares con sombra durante las horas de más sol, anotando el tipo y el estado aproximado.", "Calcula cuánta área verde hay por manzana o por tramo, destaca las zonas con menos cobertura y presenta un mapa con colores y una breve explicación."], "ampliaciones": [{"titulo": "Distancia a un parque", "aporta": "mide cuánto debe caminar una persona hasta un área verde desde distintos puntos."}, {"titulo": "Sombra a distintas horas", "aporta": "compara la sombra de la mañana, el mediodía y la tarde."}, {"titulo": "Propuestas de siembra", "aporta": "propón dónde y qué árboles añadirías."}], "objetivos": ["Diseñar un recorrido y un método de registro.", "Representar la información en un mapa.", "Calcular indicadores simples.", "Identificar zonas con mayor déficit."], "habilidades": ["Trabajo de campo.", "Lectura y creación de mapas.", "Análisis espacial básico.", "Comunicación de resultados."], "herramientas": ["Un mapa digital o una imagen satelital.", "Cuaderno de campo.", "Hoja de cálculo."], "lineamientos": ["Recorre solo espacios públicos, durante el día y de preferencia acompañado, y no fotografíes a personas ni propiedades privadas.", "Si propones cambios, aclara que son ideas para conversar con la municipalidad y los vecinos, no decisiones."], "otroSector": "El mismo mapeo sirve para ubicar bancas, bodegas, paraderos, servicios de salud o lugares accesibles."}$a58sld$::jsonb,16)
